INSERT INTO postcards (image, meta, title, season_id, story_slug, position) VALUES ('assets/stories/spring-2.webp', 'Austria · No road in', 'Three days in the orchard cabin reached only on foot', 'spring', 'cabin-in-bloom', 5);
